# =============================================================================
# analysis.R
# Workshop 4: Skin Conductance (GSR) and Heart Rate (PPG) with the Shimmer3 GSR+,
# arousal during two video commercials, analysis session
# Martin's Family Clothing Consumer Behavior Research Laboratory, JSU
#
# SIMULATED DATA. Every number this script reads was generated by
# make_simulated_data.py (seed 20278504). No person was recorded. The design follows the
# structure of the lab's own library studies "Nike Campaign Ad Evaluation" and
# "e.l.f. Campaign Ad Evaluation" (a 60 s Baseline, the commercial, a 15 s Recovery, and a
# short questionnaire; the Nike commercial is 60 s and the e.l.f. commercial 30 s) and nothing
# else about them.
#
# Design: WITHIN subjects. Every respondent watched both sequences on the lab monitor with a
# Shimmer3 GSR+ on the non-dominant hand, in counterbalanced order (Group A = Nike first,
# Group B = e.l.f. first), with a 2 minute rest between the sequences. Respondents were run two
# at a time at Seat 1 (Shimmer3-8956) and Seat 2 (Shimmer3-B, a placeholder name); the analysis
# pools both devices, as the "Multiple device aggregation" option of the GSR Peak Detection and
# Aggregation R Notebook does. The Group column is the ORDER, not a treatment.
#
# What the script does, in order:
#   0. Load packages and set paths and the figure theme
#   1. Read the simulated GSR Peak Metrics, Signal Quality, Peak Table, heart rate, survey,
#      and session log files
#   2. Merge and clean: apply the exclusion rule written in advance, flag nonresponders,
#      check the files against each other
#   3. Descriptive table by stimulus
#   4. H1: Peaks Per Minute in each commercial versus its own baseline (paired t, Wilcoxon, d_z)
#   5. H2: Nike versus e.l.f. Peaks Per Minute in the commercials (paired), mixed model of
#      commercial, order position, and a random intercept per respondent, ICC
#   6. H3: heart rate change from baseline (commercial minus baseline), each commercial and
#      the difference between them (paired)
#   7. Exploratory: self reported arousal and Peaks Per Minute
#   8. Sensitivity analysis without the nonresponders
#   9. Why Peaks Per Minute uses Signal Duration; do the two devices differ?
#  10. Moment to moment view: percent of respondents with a peak in 5 s bins with 1 s overlap
#  11. Assumption checks (plots saved to figures/)
#  12. Report figures saved as PNG, 150 dpi
#
# Sign conventions: H1 and H3 differences are commercial MINUS baseline; H2 is Nike MINUS
# e.l.f. (a positive difference means the first named value is larger).
#
# The heart rate column "Mean PPG Heart Rate (BPM)" is a MODELED name. The manuals name no PPG
# heart rate notebook or column; verify the real column on the lab machine before reusing this
# script on real data. Likewise the Signal Quality file layout, Type, Parent Stimulus, and
# M2M Bin values are modeled; the GSR Peak Metrics and Peak Table column names are the ones
# in the Export R Processed GSR Files article.
#
# How to run (either way works):
#   a) In RStudio: open this file, set the working directory to the folder that
#      holds the CSV files (Session > Set Working Directory > To Source File
#      Location), then Source.
#   b) From a terminal, inside the data folder:  Rscript analysis.R
# The console output is also written to analysis_output.txt next to the data.
#
# Packages used: readr, dplyr, tidyr, ggplot2, lme4, lmerTest, effectsize. If a package is
# missing, run once in the console:
#   install.packages(c("readr", "dplyr", "tidyr", "ggplot2", "lme4",
#                      "lmerTest", "effectsize"))
# =============================================================================

# ---- 0. Setup ---------------------------------------------------------------
suppressPackageStartupMessages({
  library(readr)
  library(dplyr)
  library(tidyr)
  library(ggplot2)
  library(lme4)
})
has_lmerTest   <- requireNamespace("lmerTest",   quietly = TRUE)
has_effectsize <- requireNamespace("effectsize", quietly = TRUE)

script_dir <- tryCatch({
  args <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", args[grep("^--file=", args)])
  if (length(f) == 1) dirname(normalizePath(f)) else getwd()
}, error = function(e) getwd())
setwd(script_dir)
fig_dir <- file.path(script_dir, "figures")
dir.create(fig_dir, showWarnings = FALSE)

output_file <- file.path(script_dir, "analysis_output.txt")
sink(output_file, split = TRUE)
cat("SIMULATED GSR and heart rate analysis, run on", format(Sys.time(), "%Y-%m-%d %H:%M"), "\n")
cat("R", R.version$major, ".", R.version$minor, "; lme4 ", as.character(packageVersion("lme4")),
    "; lmerTest available: ", has_lmerTest, "; effectsize available: ", has_effectsize, "\n\n", sep = "")

# Palette: navy (Nike), teal (e.l.f.), gray (baseline), one accent for the means and intervals.
# Panel titles, labels, and line types carry the identity as well, so color is never the only cue.
col_nike   <- "#1F3864"
col_elf    <- "#1B7F79"
col_base   <- "#8C8C8C"
col_accent <- "#A6561A"
brand_cols <- c(Nike = col_nike, elf = col_elf)

theme_gsr <- function(base_size = 13) {
  theme_minimal(base_size = base_size) +
    theme(panel.grid.minor = element_blank(),
          panel.grid.major.x = element_blank(),
          panel.grid.major.y = element_line(color = "#E3E3E3", linewidth = 0.4),
          axis.line.x = element_line(color = "#B0B0B0", linewidth = 0.4),
          plot.title = element_text(face = "bold", size = base_size + 2),
          plot.subtitle = element_text(color = "#555555"),
          plot.caption = element_text(color = "#777777", size = base_size - 3, hjust = 0),
          strip.text = element_text(face = "bold", size = base_size - 1),
          legend.position = "top",
          legend.title = element_blank(),
          plot.background = element_rect(fill = "white", color = NA))
}
save_fig <- function(plot, name, height_px = 900) {
  # 1400 px wide at 150 dpi = 9.33 in wide
  ggsave(file.path(fig_dir, name), plot, width = 1400 / 150, height = height_px / 150,
         dpi = 150, bg = "white")
  cat("saved figure:", file.path("figures", name), "\n")
}
wrap_txt <- function(x, w) paste(strwrap(x, width = w), collapse = "\n")
fp <- function(p) ifelse(p < .001, "p < .001", paste0("p = ", sub("^0", "", sprintf("%.3f", p))))
# p value for the output file: five decimals, scientific notation below 0.0001 so no p prints as 0.00000
pf <- function(p) ifelse(p < 0.0001, sprintf("%.2e", p), sprintf("%.5f", p))
# Wilcoxon V: whole number, or one decimal when ties give a half rank (for example 44.5)
fv <- function(v) ifelse(abs(v - round(v)) < 1e-9, sprintf("%.0f", v), sprintf("%.1f", v))

# ---- 1. Read the files ------------------------------------------------------
# The first line of every file is a "# SIMULATED" comment (the Peak Table has a second comment
# line, the METADATA block), so comment = "#" skips them. NA is how a metric that cannot be
# calculated is written (Average Peak Amplitude when a stimulus has no peak).
pm_raw  <- read_csv("SIMULATED_gsr_peak_metrics.csv",  comment = "#", na = c("NA", ""), show_col_types = FALSE)
sq_raw  <- read_csv("SIMULATED_gsr_signal_quality.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
pt_raw  <- read_csv("SIMULATED_gsr_peak_table.csv",    comment = "#", na = c("NA", ""), show_col_types = FALSE)
hr_raw  <- read_csv("SIMULATED_heart_rate.csv",        comment = "#", na = c("NA", ""), show_col_types = FALSE)
survey  <- read_csv("SIMULATED_gsr_survey.csv",        comment = "#", show_col_types = FALSE)
session <- read_csv("SIMULATED_gsr_session_log.csv",   comment = "#", show_col_types = FALSE)

cat("---- 1. Files read ----\n")
cat("GSR Peak Metrics rows:", nrow(pm_raw), " respondents:", n_distinct(pm_raw$`Respondent Name`),
    " stimuli:", paste(unique(pm_raw$Label), collapse = ", "), "\n")
cat("GSR Signal Quality rows:", nrow(sq_raw), "  GSR Peak Table rows (one per peak):", nrow(pt_raw),
    "  Heart rate rows:", nrow(hr_raw), "\n")
cat("Survey rows:", nrow(survey), "  Session log rows:", nrow(session), "\n")
cat("Peak Metrics columns:", paste(names(pm_raw), collapse = " | "), "\n\n")

stim_levels <- c("Baseline_Nike", "Nike_Commercial", "Recovery_Nike", "Baseline_elf", "elf_Commercial", "Recovery_elf")

pm <- pm_raw %>%
  rename(respondent = `Respondent Name`, sex = Gender, age = Age, order = Group, label = Label,
         start_ms = `Start (ms)`, dur_ms = `Duration (ms)`, sig_ms = `Signal Duration (ms)`,
         has_peaks = `Has Peaks`, n_peaks = `Peak Count`, ppm = `Peaks Per Minute`,
         amp = `Average Peak Amplitude (microSiemens)`) %>%
  mutate(label = factor(label, levels = stim_levels),
         brand = if_else(grepl("Nike", label), "Nike", "elf"),
         phase = case_when(startsWith(as.character(label), "Baseline") ~ "Baseline",
                           startsWith(as.character(label), "Recovery") ~ "Recovery",
                           TRUE ~ "Commercial"),
         # Position of the sequence in the session, from the order group: Group A saw Nike first.
         order_position = factor(if_else((order == "A") == (brand == "Nike"), "first", "second"),
                                 levels = c("first", "second")))
sq <- sq_raw %>%
  rename(respondent = `Respondent Name`, label = Stimulus, device = Device,
         snr = `Signal-to-Noise ratio (dB)`, miss_pct = `Signal missing (%)`) %>%
  select(respondent, label, device, snr, miss_pct)
hr <- hr_raw %>%
  rename(respondent = `Respondent Name`, label = Stimulus, hr_bpm = `Mean PPG Heart Rate (BPM)`) %>%
  select(respondent, label, hr_bpm)
pm <- pm %>% mutate(label = as.character(label)) %>%
  left_join(sq, by = c("respondent", "label")) %>%
  left_join(hr, by = c("respondent", "label")) %>%
  mutate(label = factor(label, levels = stim_levels))
stopifnot(!anyNA(pm$snr), !anyNA(pm$hr_bpm), nrow(pm) == 180)

# ---- 2. Merge and clean -----------------------------------------------------
# Exclusion rule, written before data collection (the lab's rule, built from the GSR Signal
# Quality article, which calls an SNR below 0 dB poor and above 20 dB good): exclude a respondent
# whose Signal-to-Noise ratio is below 0 dB or whose Signal missing is above 20 percent in ANY
# commercial. Nonresponder flag, defined from the Peak Metrics file alone: Has Peaks = 0 in at
# least 4 of the 6 stimuli. Nonresponders are KEPT in the main analysis.
cat("---- 2. Cleaning ----\n")
comm_q <- pm %>% filter(phase == "Commercial") %>%
  mutate(why = case_when(snr < 0 & miss_pct > 20 ~ "SNR below 0 dB and Signal missing above 20 percent",
                         snr < 0 ~ "SNR below 0 dB", miss_pct > 20 ~ "Signal missing above 20 percent", TRUE ~ NA_character_))
excluded <- comm_q %>% filter(!is.na(why)) %>%
  select(respondent, order, label, snr, miss_pct, why)
cat("Rule: exclude when SNR < 0 dB or Signal missing > 20 percent in any commercial.\n")
cat("Excluded respondents:\n"); print(as.data.frame(excluded), row.names = FALSE)
cat("Session log says for these respondents:\n")
for (rid in excluded$respondent) {
  s <- session %>% filter(`Respondent Name` == rid)
  cat(sprintf("  %s: Seat %d, %s, Warm up minutes = %d, Data complete = %s\n", rid, s$Seat, s$Device,
              s$`Warm up minutes`, s$`Data complete`))
  cat("  Decision note:", s$`Decision note`, "\n")
}
ex_ids <- excluded$respondent
pmk <- pm %>% filter(!respondent %in% ex_ids)
n_kept <- n_distinct(pmk$respondent)
n_by_order <- pmk %>% distinct(respondent, order) %>% count(order)
cat("\nRespondents kept per order group (A = Nike first, B = e.l.f. first):\n"); print(as.data.frame(n_by_order), row.names = FALSE)
cat("Respondents kept:", n_kept, " Excluded:", length(ex_ids), "\n")

# Signal quality of the kept data
snr_k <- pmk$snr
cat(sprintf("\nSignal quality, kept respondents (%d rows): SNR M = %.1f dB, SD = %.1f, range %.1f to %.1f; ",
            nrow(pmk), mean(snr_k), sd(snr_k), min(snr_k), max(snr_k)))
cat(sprintf("%d rows below 0 dB, %d rows from 0 to 20 dB, %d rows above 20 dB; %d rows from 18 to 32 dB (%.1f%%)\n",
            sum(snr_k < 0), sum(snr_k >= 0 & snr_k <= 20), sum(snr_k > 20), sum(snr_k >= 18 & snr_k <= 32),
            100 * mean(snr_k >= 18 & snr_k <= 32)))
cat(sprintf("Signal missing (%%), kept rows: M = %.2f, maximum = %.1f; rows with Signal Duration shorter than Duration: %d\n",
            mean(pmk$miss_pct), max(pmk$miss_pct), sum(pmk$sig_ms < pmk$dur_ms)))
low_snr <- pmk %>% group_by(respondent) %>% summarise(min_snr = min(snr), .groups = "drop") %>% filter(min_snr < 18)
cat("Kept respondents with an SNR below 18 dB in at least one row (look at the signal):",
    paste(sprintf("%s (min %.1f dB)", low_snr$respondent, low_snr$min_snr), collapse = ", "), "\n")

# Nonresponders
nr <- pmk %>% group_by(respondent) %>%
  summarise(n_zero = sum(has_peaks == 0), mean_ppm = mean(ppm), .groups = "drop") %>%
  mutate(nonresponder = n_zero >= 4)
nr_ids <- nr$respondent[nr$nonresponder]
resp_ids <- nr$respondent[!nr$nonresponder]
cat(sprintf("\nNonresponders (Has Peaks = 0 in at least 4 of 6 stimuli): %d of %d kept respondents (%.1f%%): %s\n",
            length(nr_ids), n_kept, 100 * length(nr_ids) / n_kept, paste(nr_ids, collapse = ", ")))
cat("Number of stimuli with Has Peaks = 0 for each nonresponder:",
    paste(sprintf("%s %d", nr_ids, nr$n_zero[nr$nonresponder]), collapse = ", "), "\n")
cat(sprintf("Largest number of stimuli with Has Peaks = 0 among the other kept respondents: %d\n", max(nr$n_zero[!nr$nonresponder])))
cat("Their rows in the session log (Decision note):\n")
for (rid in nr_ids) cat(sprintf("  %s: %s\n", rid, session$`Decision note`[session$`Respondent Name` == rid]))

pmk <- pmk %>% left_join(nr %>% select(respondent, nonresponder), by = "respondent")
pm  <- pm  %>% left_join(nr %>% select(respondent, nonresponder), by = "respondent")

# Check the files against each other (a real export should pass the same checks)
pt <- pt_raw %>%
  rename(respondent = `Respondent Name`, label = `Stimulus Label`, stim_start = `Stimulus Start`,
         stim_dur = `Stimulus Duration`, t_onset = `Peak Onset Time`, t_apex = `Peak Time`,
         t_offset = `Peak Offset Time`, p_amp = `Peak Amplitude`, device_pt = Device, m2m = `M2M Bin`)
pt_n <- pt %>% count(respondent, label, name = "n_table")
chk <- pm %>% mutate(label = as.character(label)) %>% left_join(pt_n, by = c("respondent", "label")) %>%
  mutate(n_table = replace_na(n_table, 0L))
pt_amp <- pt %>% group_by(respondent, label) %>% summarise(amp_table = mean(p_amp), .groups = "drop")
chk <- chk %>% left_join(pt_amp, by = c("respondent", "label"))
cat("\nConsistency checks across the exports (all 180 respondent by stimulus rows):\n")
cat(sprintf("  Peak Count equals the number of rows in the Peak Table: %s (largest gap %d)\n",
            all(chk$n_peaks == chk$n_table), max(abs(chk$n_peaks - chk$n_table))))
cat(sprintf("  Peaks Per Minute equals Peak Count / (Signal Duration / 60000): largest absolute gap = %.4f\n",
            max(abs(chk$ppm - chk$n_peaks / (chk$sig_ms / 60000)))))
cat(sprintf("  Average Peak Amplitude equals the mean Peak Amplitude in the Peak Table: largest absolute gap = %.5f\n",
            max(abs(chk$amp - chk$amp_table), na.rm = TRUE)))
cat(sprintf("  Has Peaks = 1 exactly when Peak Count > 0: %s\n", all((chk$has_peaks == 1) == (chk$n_peaks > 0))))
cat(sprintf("  Every peak lies inside its stimulus window (onset after Stimulus Start, offset before the stimulus ends): %s\n",
            all(pt$t_onset >= pt$stim_start & pt$t_offset <= pt$stim_start + pt$stim_dur)))
cat(sprintf("  Stimulus Start in the Peak Table matches Start (ms) in the Peak Metrics file: %s\n",
            all((pt %>% left_join(pm %>% mutate(label = as.character(label)) %>% select(respondent, label, start_ms), by = c("respondent", "label")) %>%
                   mutate(ok = stim_start == start_ms) %>% pull(ok)))))
cat(sprintf("  Device in the Peak Table matches Device in the Signal Quality file: %s\n",
            all((pt %>% left_join(distinct(sq_raw %>% rename(respondent = `Respondent Name`) %>% select(respondent, device_sq = Device)), by = "respondent") %>%
                   mutate(ok = device_pt == device_sq) %>% pull(ok)))))
cat("\n")

# Wide tables, one row per kept respondent
ppm_w <- pmk %>% select(respondent, order, nonresponder, label, ppm) %>% pivot_wider(names_from = label, values_from = ppm)
hr_w  <- pmk %>% select(respondent, order, nonresponder, label, hr_bpm) %>% pivot_wider(names_from = label, values_from = hr_bpm)

# ---- 3. Descriptive table by stimulus ---------------------------------------
desc <- pmk %>%
  group_by(label) %>%
  summarise(duration_s = first(dur_ms) / 1000,
            n = n(),
            ppm_mean = mean(ppm), ppm_sd = sd(ppm), ppm_median = median(ppm), ppm_min = min(ppm), ppm_max = max(ppm),
            pct_has_peaks = round(100 * mean(has_peaks), 1),
            peak_count_mean = mean(n_peaks),
            n_amp = sum(!is.na(amp)), amp_mean = mean(amp, na.rm = TRUE), amp_sd = sd(amp, na.rm = TRUE),
            hr_mean_bpm = mean(hr_bpm), hr_sd_bpm = sd(hr_bpm),
            snr_mean_db = mean(snr), snr_sd_db = sd(snr),
            missing_mean_pct = mean(miss_pct), signal_dur_mean_ms = mean(sig_ms),
            .groups = "drop") %>%
  rename(stimulus = label) %>%
  mutate(stimulus = as.character(stimulus), across(where(is.double), ~ round(.x, 3))) %>%
  arrange(match(stimulus, stim_levels))
cat("---- 3. Descriptive table by stimulus (kept respondents) ----\n")
print(as.data.frame(desc[, c("stimulus", "duration_s", "n", "ppm_mean", "ppm_sd", "ppm_median", "ppm_min", "ppm_max",
                             "pct_has_peaks", "peak_count_mean")]), row.names = FALSE)
cat("\n")
print(as.data.frame(desc[, c("stimulus", "n_amp", "amp_mean", "amp_sd", "hr_mean_bpm", "hr_sd_bpm", "snr_mean_db", "snr_sd_db",
                             "missing_mean_pct", "signal_dur_mean_ms")]), row.names = FALSE)
write_csv(desc, "SIMULATED_descriptives_by_stimulus.csv")
cat("written: SIMULATED_descriptives_by_stimulus.csv\n\n")

cor_pair <- function(a, b) cor(ppm_w[[a]], ppm_w[[b]])
r_bn <- cor_pair("Baseline_Nike", "Nike_Commercial"); r_be <- cor_pair("Baseline_elf", "elf_Commercial")
r_ne <- cor_pair("Nike_Commercial", "elf_Commercial")
cat("Within respondent correlations of Peaks Per Minute (all kept respondents):\n")
cat(sprintf("  Baseline_Nike with Nike_Commercial: r = %.2f\n  Baseline_elf with elf_Commercial: r = %.2f\n  Nike_Commercial with elf_Commercial: r = %.2f\n",
            r_bn, r_be, r_ne))
cat(sprintf("  Mean of the three correlations: r = %.2f\n", mean(c(r_bn, r_be, r_ne))))
d_ <- function(l) desc[desc$stimulus == l, ]
amp_base_all <- pmk %>% filter(phase == "Baseline", !is.na(amp)) %>% pull(amp)
cat("Realized versus planned (generator assumptions in make_simulated_data.py):\n")
cat(sprintf("  Peaks Per Minute, Baseline_Nike: M = %.2f, SD = %.2f (planned 2.4, 1.3)\n", d_("Baseline_Nike")$ppm_mean, d_("Baseline_Nike")$ppm_sd))
cat(sprintf("  Peaks Per Minute, Baseline_elf: M = %.2f, SD = %.2f (planned 2.4, 1.3)\n", d_("Baseline_elf")$ppm_mean, d_("Baseline_elf")$ppm_sd))
cat(sprintf("  Peaks Per Minute, Nike_Commercial: M = %.2f, SD = %.2f (planned 4.6, 2.0)\n", d_("Nike_Commercial")$ppm_mean, d_("Nike_Commercial")$ppm_sd))
cat(sprintf("  Peaks Per Minute, elf_Commercial: M = %.2f, SD = %.2f (planned 3.7, 1.8)\n", d_("elf_Commercial")$ppm_mean, d_("elf_Commercial")$ppm_sd))
cat(sprintf("  Peaks Per Minute, recoveries: M = %.2f (Nike) and %.2f (e.l.f.) (planned about 3.0)\n", d_("Recovery_Nike")$ppm_mean, d_("Recovery_elf")$ppm_mean))
cat(sprintf("  Average Peak Amplitude (microSiemens): baselines %.2f, Nike_Commercial %.2f, elf_Commercial %.2f (planned 0.20, 0.28, 0.25)\n",
            mean(amp_base_all), d_("Nike_Commercial")$amp_mean, d_("elf_Commercial")$amp_mean))
hr_base_all <- c(hr_w$Baseline_Nike, hr_w$Baseline_elf)
cat(sprintf("  Baseline heart rate (BPM): M = %.1f, SD = %.1f (planned 74, 9)\n\n", mean(hr_base_all), sd(hr_base_all)))

# ---- Helper: paired t test plus Cohen's d_z with a 95 percent CI ------------
# difference = x2 minus x1. Cohen's d_z = mean difference / SD of the differences, the effect
# size that goes with a paired t test (t = d_z * sqrt(n)). The CI comes from
# effectsize::cohens_d on the differences (noncentral t method) when the package is installed;
# otherwise from the large sample approximation SE(d_z) = sqrt(1 / n + d_z^2 / (2 n)).
report_paired <- function(x1, x2, label, unit, nm1, nm2, id = NA_character_) {
  ok <- !is.na(x1) & !is.na(x2)
  a <- x1[ok]; b <- x2[ok]; dif <- b - a; n <- length(dif)
  tt <- t.test(b, a, paired = TRUE)
  dz <- mean(dif) / sd(dif)
  if (has_effectsize) {
    es <- effectsize::cohens_d(dif, ci = 0.95)
    stopifnot(abs(es$Cohens_d - dz) < 1e-8)
    dz_lo <- es$CI_low; dz_hi <- es$CI_high; ci_method <- "noncentral t (effectsize)"
  } else {
    se_d <- sqrt(1 / n + dz^2 / (2 * n))
    dz_lo <- dz - 1.96 * se_d; dz_hi <- dz + 1.96 * se_d; ci_method <- "large sample approximation"
  }
  wx <- suppressWarnings(wilcox.test(b, a, paired = TRUE, exact = FALSE))
  sw <- shapiro.test(dif)
  cat(sprintf("%s\n", label))
  cat(sprintf("  %s: M = %.2f %s, SD = %.2f, n = %d\n", nm1, mean(a), unit, sd(a), n))
  cat(sprintf("  %s: M = %.2f %s, SD = %.2f, n = %d\n", nm2, mean(b), unit, sd(b), n))
  cat(sprintf("  Mean difference (%s minus %s) = %.2f %s, SD of differences = %.2f, 95%% CI [%.2f, %.2f]\n",
              nm2, nm1, mean(dif), unit, sd(dif), tt$conf.int[1], tt$conf.int[2]))
  cat(sprintf("  Paired t(%d) = %.2f, p = %s\n", as.integer(tt$parameter), tt$statistic, pf(tt$p.value)))
  cat(sprintf("  Cohen's d_z = %.2f, 95%% CI [%.2f, %.2f]  (%s)\n", dz, dz_lo, dz_hi, ci_method))
  cat(sprintf("  Wilcoxon signed rank V = %s, p = %s\n", fv(wx$statistic), pf(wx$p.value)))
  cat(sprintf("  Shapiro Wilk on the differences: W = %.3f, p = %.3f\n\n", sw$statistic, sw$p.value))
  invisible(list(id = id, label = label, n = n, m_1 = mean(a), m_2 = mean(b), sd_1 = sd(a), sd_2 = sd(b),
                 diff = mean(dif), sd_diff = sd(dif), ci_lo = tt$conf.int[1], ci_hi = tt$conf.int[2],
                 t = unname(tt$statistic), df = unname(tt$parameter), p = tt$p.value,
                 dz = dz, dz_lo = dz_lo, dz_hi = dz_hi, V = unname(wx$statistic), p_w = wx$p.value,
                 shapiro_p = sw$p.value, dif = dif))
}

# ---- 4. H1: arousal response, commercial versus its own baseline -------------
# H1: Peaks Per Minute is higher during each commercial than during the Baseline that preceded
# it. Peaks Per Minute is a rate, so the 60 s baseline and the 30 s commercial are comparable;
# for the e.l.f. commercial the rate rests on a 30 s window, so it moves in steps of 2.
cat("---- 4. H1: Peaks Per Minute, commercial versus its own baseline (paired) ----\n")
res_h1n <- report_paired(ppm_w$Baseline_Nike, ppm_w$Nike_Commercial,
                         "Nike: Peaks Per Minute (all kept respondents)", "peaks per minute", "Baseline_Nike", "Nike_Commercial", "H1_Nike")
res_h1e <- report_paired(ppm_w$Baseline_elf, ppm_w$elf_Commercial,
                         "e.l.f.: Peaks Per Minute (all kept respondents)", "peaks per minute", "Baseline_elf", "elf_Commercial", "H1_elf")
up_n <- sum(ppm_w$Nike_Commercial > ppm_w$Baseline_Nike); dn_n <- sum(ppm_w$Nike_Commercial < ppm_w$Baseline_Nike)
up_e <- sum(ppm_w$elf_Commercial > ppm_w$Baseline_elf);   dn_e <- sum(ppm_w$elf_Commercial < ppm_w$Baseline_elf)
cat(sprintf("Respondents with more peaks per minute in the commercial than in its baseline: Nike %d of %d (lower for %d, equal for %d); e.l.f. %d of %d (lower for %d, equal for %d)\n",
            up_n, n_kept, dn_n, n_kept - up_n - dn_n, up_e, n_kept, dn_e, n_kept - up_e - dn_e))
cat(sprintf("Respondents with at least one peak during the commercial (respondent ratio): Nike %d of %d (%.1f%%); e.l.f. %d of %d (%.1f%%)\n\n",
            sum(ppm_w$Nike_Commercial > 0), n_kept, 100 * mean(ppm_w$Nike_Commercial > 0),
            sum(ppm_w$elf_Commercial > 0), n_kept, 100 * mean(ppm_w$elf_Commercial > 0)))

# ---- 5. H2: Nike versus e.l.f. ----------------------------------------------
cat("---- 5. H2: Peaks Per Minute in the commercials, Nike versus e.l.f. (paired) ----\n")
res_h2 <- report_paired(ppm_w$elf_Commercial, ppm_w$Nike_Commercial,
                        "Peaks Per Minute in the commercials (all kept respondents)", "peaks per minute", "elf_Commercial", "Nike_Commercial", "H2")
cat(sprintf("Nike_Commercial was higher than elf_Commercial for %d of %d respondents (lower for %d, equal for %d)\n\n",
            sum(ppm_w$Nike_Commercial > ppm_w$elf_Commercial), n_kept, sum(ppm_w$Nike_Commercial < ppm_w$elf_Commercial),
            sum(ppm_w$Nike_Commercial == ppm_w$elf_Commercial)))

# Carryover check. Each respondent contributes two commercial rows, so the rows are not
# independent; a random intercept for respondent absorbs the tendency to produce many or few
# peaks overall. order_position says whether the commercial was seen first or second; the
# generator built in habituation (0.4 fewer peaks per minute for the commercial seen second
# and 0.4 more for the one seen first, a second minus first difference of -0.8).
# The two factors are coded -0.5 / +0.5 (commercial: elf = -0.5, Nike = +0.5; order_position:
# first = -0.5, second = +0.5), so each coefficient is the full difference between the two
# levels, averaged over the other factor:
#   commercial1                  = Nike minus e.l.f.
#   order_position1              = second minus first (the order effect)
#   commercial1:order_position1  = difference of differences
# Group (A or B) fixes which commercial is first, so the interaction is the same contrast as
# the A versus B difference in a respondent's total, a between respondents comparison with its
# own (smaller) degrees of freedom.
cat("---- 5b. Mixed model: ppm ~ commercial * order_position + (1 | respondent), commercials only ----\n")
mm_data <- pmk %>% filter(phase == "Commercial") %>%
  transmute(respondent, order, commercial = factor(brand, levels = c("elf", "Nike")), order_position, ppm) %>%
  as.data.frame()
contrasts(mm_data$commercial)     <- c(-0.5, 0.5)
contrasts(mm_data$order_position) <- c(-0.5, 0.5)
if (has_lmerTest) {
  mm <- lmerTest::lmer(ppm ~ commercial * order_position + (1 | respondent), data = mm_data, REML = TRUE)
  print(summary(mm, correlation = FALSE))
  cat("\nType III tests (Satterthwaite degrees of freedom):\n")
  print(anova(mm, type = 3))
} else {
  mm <- lme4::lmer(ppm ~ commercial * order_position + (1 | respondent), data = mm_data, REML = TRUE)
  print(summary(mm, correlation = FALSE))
  cat("\nlmerTest is not installed, so no p values are printed.\n")
}
cf <- as.data.frame(coef(summary(mm)))
if (has_lmerTest) {
  names(cf) <- c("est", "se", "df", "t", "p")
  cf$ci_lo <- cf$est - qt(0.975, cf$df) * cf$se
  cf$ci_hi <- cf$est + qt(0.975, cf$df) * cf$se
} else {
  names(cf) <- c("est", "se", "t")
  cf$df <- NA_real_; cf$p <- NA_real_; cf$ci_lo <- cf$est - 1.96 * cf$se; cf$ci_hi <- cf$est + 1.96 * cf$se
}
term_labels <- c("(Intercept)" = "Intercept (grand mean)",
                 "commercial1" = "Commercial (Nike minus elf)",
                 "order_position1" = "Order position (second minus first)",
                 "commercial1:order_position1" = "Commercial x order position")
cat("\nFixed effects with 95% CI (estimate +/- t(Satterthwaite df) x SE):\n")
for (nm in rownames(cf)) {
  cat(sprintf("  %-38s b = %6.2f, SE = %.2f, df = %5.1f, t = %6.2f, p = %s, 95%% CI [%.2f, %.2f]\n",
              term_labels[[nm]], cf[nm, "est"], cf[nm, "se"], cf[nm, "df"], cf[nm, "t"], pf(cf[nm, "p"]),
              cf[nm, "ci_lo"], cf[nm, "ci_hi"]))
}
vc <- as.data.frame(VarCorr(mm))
var_resp <- vc$vcov[vc$grp == "respondent"]; var_res <- vc$vcov[vc$grp == "Residual"]
icc_adj <- var_resp / (var_resp + var_res)
mm0 <- lme4::lmer(ppm ~ 1 + (1 | respondent), data = mm_data, REML = TRUE)
vc0 <- as.data.frame(VarCorr(mm0))
icc_null <- vc0$vcov[vc0$grp == "respondent"] / sum(vc0$vcov)
cat(sprintf("\nICC (adjusted, from the fitted model) = %.3f  (respondent variance %.2f, residual variance %.2f)\n",
            icc_adj, var_resp, var_res))
cat(sprintf("ICC (unconditional, intercept only model) = %.3f\n", icc_null))
cat(sprintf("Correlation of a respondent's two commercial Peaks Per Minute values (raw): r = %.2f\n", r_ne))

# Simple within respondent estimate of the order effect (Excel can reproduce it). The difference
# Nike minus elf is (commercial effect - order effect) for Group A (Nike first) and
# (commercial effect + order effect) for Group B (Nike second).
dA <- res_h2$dif[ppm_w$order == "A"]; dB <- res_h2$dif[ppm_w$order == "B"]
order_simple <- (mean(dB) - mean(dA)) / 2
comm_simple  <- (mean(dA) + mean(dB)) / 2
cat(sprintf("Simple estimate of the order effect = (mean difference in Group B - mean difference in Group A) / 2 = (%.2f - %.2f) / 2 = %.2f (n = %d and %d)\n",
            mean(dB), mean(dA), order_simple, length(dB), length(dA)))
cat(sprintf("Simple estimate of the commercial effect (order adjusted) = (%.2f + %.2f) / 2 = %.2f\n", mean(dA), mean(dB), comm_simple))
cell_means <- pmk %>% filter(phase == "Commercial") %>% group_by(brand, order_position) %>%
  summarise(n = n(), mean_ppm = round(mean(ppm), 2), sd_ppm = round(sd(ppm), 2), .groups = "drop")
cat("\nRaw cell means of Peaks Per Minute in the commercials:\n"); print(as.data.frame(cell_means), row.names = FALSE)
cat("\n")

# ---- 6. H3: heart rate change from baseline ---------------------------------
# H3: mean heart rate (from the PPG channel) is lower during a commercial than during its
# baseline (a deceleration), and the change differs between the commercials. Heart rate change
# = commercial mean minus the mean of the Baseline that preceded it.
