                         "e.l.f.: mean heart rate (all kept respondents)", "BPM", "Baseline_elf", "elf_Commercial", "H3_elf")
hr_w <- hr_w %>% mutate(chg_Nike = Nike_Commercial - Baseline_Nike, chg_elf = elf_Commercial - Baseline_elf)
res_h3d <- report_paired(hr_w$chg_elf, hr_w$chg_Nike,
                         "Difference between the heart rate changes (all kept respondents)", "BPM", "Change_elf", "Change_Nike", "H3_diff")
cat(sprintf("Heart rate was lower in the commercial than in its baseline for %d of %d respondents (Nike) and %d of %d (e.l.f.)\n",
            sum(hr_w$chg_Nike < 0), n_kept, sum(hr_w$chg_elf < 0), n_kept))
cat(sprintf("Correlation of baseline heart rate with the commercial heart rate: Nike r = %.2f, e.l.f. r = %.2f\n",
            cor(hr_w$Baseline_Nike, hr_w$Nike_Commercial), cor(hr_w$Baseline_elf, hr_w$elf_Commercial)))
cat(sprintf("Baseline heart rate (both baselines pooled): M = %.1f BPM, SD = %.1f\n\n", mean(hr_base_all), sd(hr_base_all)))

# ---- 7. Exploratory: self reported arousal and Peaks Per Minute --------------
