            mean(link$lk_Nike), sd(link$lk_Nike), mean(link$lk_elf), sd(link$lk_elf)))
cor_report <- function(x, y, label, id) {
  ct <- cor.test(x, y)
  sp <- suppressWarnings(cor.test(x, y, method = "spearman", exact = FALSE))
  cat(sprintf("%s: r(%d) = %.2f, 95%% CI [%.2f, %.2f], p = %s; Spearman rho = %.2f, p = %s\n",
              label, as.integer(ct$parameter), ct$estimate, ct$conf.int[1], ct$conf.int[2], pf(ct$p.value),
              sp$estimate, pf(sp$p.value)))
  invisible(list(id = id, label = label, r = unname(ct$estimate), df = unname(ct$parameter), t = unname(ct$statistic),
                 p = ct$p.value, lo = ct$conf.int[1], hi = ct$conf.int[2], rho = unname(sp$estimate), p_rho = sp$p.value))
}
c_n <- cor_report(link$ar_Nike, link$ppm_Nike, "Nike_Commercial Peaks Per Minute with Arousal_Nike_1to9", "cor_Nike")
c_e <- cor_report(link$ar_elf, link$ppm_elf, "elf_Commercial Peaks Per Minute with Arousal_elf_1to9", "cor_elf")
link <- link %>% mutate(ar_mean = (ar_Nike + ar_elf) / 2, ppm_mean = (ppm_Nike + ppm_elf) / 2)
c_m <- cor_report(link$ar_mean, link$ppm_mean, "Respondent means over the two commercials (arousal with Peaks Per Minute)", "cor_mean")
cat(sprintf("Nonresponders' self reported arousal (mean of the two commercials): M = %.2f (n = %d) versus %.2f for the other respondents (n = %d)\n\n",
            mean(link$ar_mean[link$nonresponder]), sum(link$nonresponder), mean(link$ar_mean[!link$nonresponder]), sum(!link$nonresponder)))

# ---- 8. Sensitivity analysis without the nonresponders -----------------------
cat("---- 8. Sensitivity: the same tests without the nonresponders ----\n")
cat(sprintf("Nonresponders removed: %s; n = %d responders remain\n\n", paste(nr_ids, collapse = ", "), length(resp_ids)))
pr <- ppm_w %>% filter(!nonresponder)
