                        "Sensitivity H2: Peaks Per Minute in the commercials (responders only)", "peaks per minute", "elf_Commercial", "Nike_Commercial", "S_H2")
dA_r <- res_s2$dif[pr$order == "A"]; dB_r <- res_s2$dif[pr$order == "B"]
order_simple_r <- (mean(dB_r) - mean(dA_r)) / 2
