            cor(pr$Baseline_Nike, pr$Nike_Commercial), cor(pr$Baseline_elf, pr$elf_Commercial), cor(pr$Nike_Commercial, pr$elf_Commercial)))
lr <- link %>% filter(!nonresponder)
c_nr <- cor_report(lr$ar_Nike, lr$ppm_Nike, "Responders only: Nike_Commercial Peaks Per Minute with Arousal_Nike_1to9", "S_cor_Nike")
c_er <- cor_report(lr$ar_elf, lr$ppm_elf, "Responders only: elf_Commercial Peaks Per Minute with Arousal_elf_1to9", "S_cor_elf")
nrp <- pmk %>% filter(nonresponder, phase != "Recovery") %>% summarise(ppm = mean(ppm))
rsp <- pmk %>% filter(!nonresponder, phase != "Recovery") %>% summarise(ppm = mean(ppm))
cat(sprintf("Mean Peaks Per Minute over the four baseline and commercial stimuli: nonresponders %.2f, responders %.2f\n", nrp$ppm, rsp$ppm))
cat(sprintf("Heart rate change is not affected by GSR nonresponse (PPG is a separate sensor): the nonresponders' mean change was %.2f BPM (Nike) and %.2f BPM (e.l.f.) versus %.2f and %.2f for the responders\n\n",
            mean(hr_w$chg_Nike[hr_w$nonresponder]), mean(hr_w$chg_elf[hr_w$nonresponder]),
            mean(hr_w$chg_Nike[!hr_w$nonresponder]), mean(hr_w$chg_elf[!hr_w$nonresponder])))

# ---- 9. Why Peaks Per Minute uses Signal Duration; do the devices differ? -----
cat("---- 9. Why Peaks Per Minute divides by Signal Duration ----\n")
cat("Peaks Per Minute = Peak Count / (Signal Duration / 60000). Signal Duration leaves out gaps longer than 4 s,\n")
cat("so a Bluetooth dropout shortens the time in which a peak could have been detected. Dividing by Duration\n")
cat("would treat the gap as time with no arousal. Rows where Signal Duration is shorter than Duration (all 30 respondents):\n")
sd_tab <- pm %>% filter(sig_ms < dur_ms) %>%
  transmute(respondent, label = as.character(label), dur_ms, sig_ms, miss_pct, n_peaks,
            ppm_signal = round(n_peaks / (sig_ms / 60000), 3), ppm_duration = round(n_peaks / (dur_ms / 60000), 3),
            understatement = round(ppm_signal - ppm_duration, 3), kept = !respondent %in% ex_ids)
print(as.data.frame(sd_tab), row.names = FALSE)
cat(sprintf("Largest understatement of Peaks Per Minute if Duration were used instead of Signal Duration: %.3f peaks per minute (%s %s)\n",
            max(sd_tab$understatement), sd_tab$respondent[which.max(sd_tab$understatement)], sd_tab$label[which.max(sd_tab$understatement)]))
cat(sprintf("Among kept respondents: %d rows with a gap, largest understatement %.3f peaks per minute\n\n",
            sum(sd_tab$kept), max(sd_tab$understatement[sd_tab$kept])))

cat("Device check (the analysis pools Seat 1 and Seat 2; Device comes from the Signal Quality file):\n")
dev_resp <- pmk %>% group_by(respondent, device) %>%
  summarise(ppm_resp = mean(ppm[phase != "Recovery"]), snr_resp = mean(snr), .groups = "drop")
dev_tab <- dev_resp %>% group_by(device) %>%
  summarise(n_respondents = n(), snr_mean_db = round(mean(snr_resp), 2), snr_sd_db = round(sd(snr_resp), 2),
            ppm_mean = round(mean(ppm_resp), 2), ppm_sd = round(sd(ppm_resp), 2), .groups = "drop")
print(as.data.frame(dev_tab), row.names = FALSE)
w_snr <- t.test(snr_resp ~ device, data = dev_resp)
w_ppm <- t.test(ppm_resp ~ device, data = dev_resp)
cat(sprintf("Welch t test of respondent mean SNR between devices: t(%.1f) = %.2f, p = %s\n", w_snr$parameter, w_snr$statistic, pf(w_snr$p.value)))
cat(sprintf("Welch t test of respondent mean Peaks Per Minute (baselines and commercials) between devices: t(%.1f) = %.2f, p = %s\n\n",
            w_ppm$parameter, w_ppm$statistic, pf(w_ppm$p.value)))

# ---- 10. Moment to moment: percent of respondents with a peak in each bin -----
# GSR Peak Binned Aggregation (manual defaults): Time bin length 5 s, Time bin overlap 1 s, so a
# new bin starts every 4 s. A bin scores 1 for a respondent when it holds at least one peak (here the
# peak apex, Peak Time); the scores are summed over respondents. Only complete bins are used.
cat("---- 10. Moment to moment view: percent of kept respondents with a peak in each 5 s bin (1 s overlap) ----\n")
bin_def <- function(d_s) { k <- 0:floor((d_s - 5) / 4); tibble(bin = k + 1, start_s = 4 * k, end_s = 4 * k + 5) }
m2m_one <- function(lab, d_s) {
  pk <- pt %>% filter(label == lab, respondent %in% pmk$respondent) %>% mutate(t_s = (t_apex - stim_start) / 1000)
  bd <- bin_def(d_s)
  bd$n_resp <- sapply(seq_len(nrow(bd)), function(i)
    n_distinct(pk$respondent[pk$t_s >= bd$start_s[i] & pk$t_s < bd$end_s[i]]))
  bd$pct <- 100 * bd$n_resp / n_kept
  bd$commercial <- lab
  bd
}
m2m <- bind_rows(m2m_one("Nike_Commercial", 60), m2m_one("elf_Commercial", 30))
# check the modeled M2M Bin label in the Peak Table against the bins computed here
first_bin_calc <- function(t_s, d_s) { bd <- bin_def(d_s); sapply(t_s, function(t) { i <- which(bd$start_s <= t & t < bd$end_s); if (length(i)) min(i) else NA_integer_ }) }
pt_chk <- pt %>% filter(label %in% c("Nike_Commercial", "elf_Commercial")) %>%
  mutate(t_s = (t_apex - stim_start) / 1000, d_s = stim_dur / 1000,
         bin_label = as.integer(sub("\\[.*", "", m2m)),
         bin_calc = mapply(function(t, d) first_bin_calc(t, d), t_s, d_s))
cat(sprintf("M2M Bin label in the Peak Table agrees with the first bin computed here for all %d commercial peaks: %s\n",
            nrow(pt_chk), all(pt_chk$bin_label == pt_chk$bin_calc, na.rm = TRUE) && !anyNA(pt_chk$bin_calc)))
for (lab in c("Nike_Commercial", "elf_Commercial")) {
  mm_ <- m2m %>% filter(commercial == lab)
  cat(sprintf("\n%s (%d complete bins of 5 s, n = %d respondents)\n", lab, nrow(mm_), n_kept))
  print(as.data.frame(mm_ %>% transmute(bin, window_s = sprintf("%d-%d", start_s, end_s), n_resp, pct = round(pct, 1))), row.names = FALSE)
  hi <- mm_[which.max(mm_$pct), ]; lo <- mm_[which.min(mm_$pct), ]
  cat(sprintf("  Mean over bins = %.1f%%; highest bin %d (%d to %d s) = %.1f%% (%d respondents); lowest bin %d (%d to %d s) = %.1f%%; first bin = %.1f%%\n",
              mean(mm_$pct), hi$bin, hi$start_s, hi$end_s, hi$pct, hi$n_resp, lo$bin, lo$start_s, lo$end_s, lo$pct, mm_$pct[1]))
}
cat("\n")

