                      "H3 Nike: heart rate change (BPM)", "H3 e.l.f.: heart rate change (BPM)", "H3 difference of changes (BPM)"),
             n = c(res_h1n$n, res_h1e$n, res_h2$n, res_h3n$n, res_h3e$n, res_h3d$n),
             shapiro_p = round(c(res_h1n$shapiro_p, res_h1e$shapiro_p, res_h2$shapiro_p, res_h3n$shapiro_p, res_h3e$shapiro_p, res_h3d$shapiro_p), 3))
cat("Shapiro Wilk p for the paired differences (a low p flags non-normality; small n limits power):\n")
print(as.data.frame(sw), row.names = FALSE)
cat(sprintf("Shapiro Wilk p for the mixed model residuals: %.3f\n", shapiro.test(resid(mm))$p.value))
re_int <- ranef(mm)$respondent[, 1]
cat(sprintf("Shapiro Wilk p for the respondent random intercepts: %.3f\n", shapiro.test(re_int)$p.value))
cat("Peaks Per Minute is built from whole peak counts (a 30 s window gives steps of 2), so the differences cannot be perfectly normal; the Wilcoxon results above are the companion check.\n")

