ci95 <- function(x) { x <- x[!is.na(x)]; qt(0.975, length(x) - 1) * sd(x) / sqrt(length(x)) }
strip_lab <- function(nm, r) sprintf("%s\nt(%d) = %.2f, %s, d_z = %.2f", nm, as.integer(r$df), r$t, fp(r$p), r$dz)

# Figure 1: Peaks Per Minute, baseline versus commercial, paired lines for both commercials.
set.seed(20278504)
f1_long <- bind_rows(
  ppm_w %>% transmute(respondent, nonresponder, commercial = "Nike", Baseline = Baseline_Nike, Commercial = Nike_Commercial),
  ppm_w %>% transmute(respondent, nonresponder, commercial = "elf",  Baseline = Baseline_elf,  Commercial = elf_Commercial)) %>%
  mutate(jit = runif(n(), -0.15, 0.15)) %>%
