         commercial = factor(commercial, levels = c("Nike", "elf")))
f1_mean <- f1_long %>% group_by(commercial, phase, x) %>% summarise(mean = mean(y), ci = ci95(y), .groups = "drop") %>%
  mutate(xo = x + if_else(x == 1, -0.26, 0.26), hj = if_else(x == 1, 1.35, -0.35))
lab_f1 <- c(Nike = strip_lab("Nike commercial (60 s)", res_h1n), elf = strip_lab("e.l.f. commercial (30 s)", res_h1e))
fig1 <- ggplot() +
  geom_line(data = f1_long, aes(x = x, y = yj, group = respondent, linetype = nonresponder), color = "#B8B8B8", linewidth = 0.5) +
  geom_point(data = f1_long %>% filter(!nonresponder), aes(x = x, y = yj, color = interaction(phase, commercial)), size = 2.3, alpha = 0.85) +
  geom_point(data = f1_long %>% filter(nonresponder), aes(x = x, y = yj, color = interaction(phase, commercial)), size = 3.4, shape = 1, stroke = 1.1) +
  geom_errorbar(data = f1_mean, aes(x = xo, ymin = mean - ci, ymax = mean + ci), width = 0.07, linewidth = 0.9, color = col_accent) +
  geom_point(data = f1_mean, aes(x = xo, y = mean), size = 4.2, color = col_accent) +
  geom_text(data = f1_mean, aes(x = xo, y = mean, label = sprintf("M = %.2f", mean), hjust = hj), size = 3.7, color = "#333333") +
  scale_color_manual(values = c(Baseline.Nike = col_base, Commercial.Nike = col_nike, Baseline.elf = col_base, Commercial.elf = col_elf), guide = "none") +
  scale_linetype_manual(values = c(`FALSE` = "solid", `TRUE` = "dotted"), guide = "none") +
  scale_x_continuous(breaks = 1:2, labels = c("Baseline", "Commercial"), limits = c(0.4, 2.6)) +
  scale_y_continuous(breaks = seq(0, 8, 2)) +
  coord_cartesian(ylim = c(-0.45, 8.3)) +
  facet_wrap(~ commercial, labeller = labeller(commercial = lab_f1)) +
  labs(title = "Peaks per minute: each commercial against its own baseline",
       subtitle = wrap_txt(sprintf("Each line is one respondent (points jittered slightly); mean with 95%% CI in accent. n = %d.", n_kept), 100),
       x = NULL, y = "GSR peaks per minute",
       caption = wrap_txt(sprintf("SIMULATED teaching data (make_simulated_data.py). Not real viewers. Open circles and dotted lines: the %d nonresponders (Has Peaks = 0 in at least 4 of 6 stimuli). Peaks per minute = Peak Count / Signal Duration; the 30 s e.l.f. commercial moves in steps of 2.", length(nr_ids)), 125)) +
  theme_gsr() + theme(legend.position = "none")
save_fig(fig1, "SIMULATED_fig1_peaks_per_minute.png", 950)

# Figure 2: moment to moment, percent of respondents with a peak in 5 s bins (1 s overlap).
m2m_plot <- m2m %>% mutate(mid_s = (start_s + end_s) / 2,
                           panel = factor(commercial, levels = c("Nike_Commercial", "elf_Commercial"),
                                          labels = c("Nike commercial (60 s)", "e.l.f. commercial (30 s)")))
m2m_mean <- m2m_plot %>% group_by(panel) %>% summarise(mean_pct = mean(pct), .groups = "drop")
m2m_hi <- m2m_plot %>% group_by(panel) %>% slice_max(pct, n = 1, with_ties = FALSE) %>% ungroup() %>%
  mutate(lab = sprintf("%.0f%% (%d to %d s)", pct, start_s, end_s))
fig2 <- ggplot(m2m_plot, aes(x = mid_s, y = pct)) +
  geom_ribbon(aes(ymin = 0, ymax = pct, fill = commercial), alpha = 0.18) +
  geom_hline(data = m2m_mean, aes(yintercept = mean_pct), linetype = "dashed", color = col_accent, linewidth = 0.6) +
  geom_line(aes(color = commercial), linewidth = 0.9) +
  geom_point(aes(color = commercial), size = 2.2) +
  geom_text(data = m2m_hi, aes(label = lab), vjust = -0.9, size = 3.5, color = "#333333") +
  scale_color_manual(values = c(Nike_Commercial = col_nike, elf_Commercial = col_elf), guide = "none") +
  scale_fill_manual(values = c(Nike_Commercial = col_nike, elf_Commercial = col_elf), guide = "none") +
  scale_x_continuous(breaks = seq(0, 60, 10)) +
  scale_y_continuous(limits = c(0, 70), expand = expansion(mult = c(0, 0.02))) +
  facet_grid(. ~ panel, scales = "free_x", space = "free_x") +
  labs(title = "Moment to moment: when did viewers produce GSR peaks?",
       subtitle = wrap_txt(sprintf("Percent of respondents with at least one peak in each 5 s bin (bins overlap by 1 s); n = %d. Dashed line: mean over bins (Nike %.0f%%, e.l.f. %.0f%%).",
                                   n_kept, m2m_mean$mean_pct[1], m2m_mean$mean_pct[2]), 100),
       x = "Seconds from the start of the commercial (bin midpoint)", y = "Respondents with a peak in the bin (%)",
       caption = wrap_txt("SIMULATED teaching data. The time profile inside each commercial is invented and says nothing about the real commercials. GSR Peak Binned Aggregation defaults: Time bin length 5 s, Time bin overlap 1 s. A peak counts in a bin when its apex falls inside it.", 125)) +
  theme_gsr()
save_fig(fig2, "SIMULATED_fig2_moment_to_moment.png", 900)

# Figure 3: heart rate change from baseline.
set.seed(20278504)
f3_long <- hr_w %>% select(respondent, Nike = chg_Nike, elf = chg_elf) %>%
  pivot_longer(c(Nike, elf), names_to = "commercial", values_to = "y") %>%
