  geom_point(data = f3_long, aes(x = x, y = y, color = commercial), size = 2.4, alpha = 0.85) +
  geom_errorbar(data = f3_mean, aes(x = xo, ymin = mean - ci, ymax = mean + ci), width = 0.07, linewidth = 0.9, color = col_accent) +
  geom_point(data = f3_mean, aes(x = xo, y = mean), size = 4.2, color = col_accent) +
  geom_text(data = f3_mean, aes(x = xo, y = mean, label = sprintf("M = %.2f", mean), hjust = hj), size = 3.8, color = "#333333") +
  scale_color_manual(values = brand_cols, guide = "none") +
  scale_x_continuous(breaks = 1:2, labels = c("Nike commercial\n(60 s)", "e.l.f. commercial\n(30 s)"), limits = c(0.35, 2.65)) +
  labs(title = "Heart rate change from baseline (commercial minus baseline)",
       subtitle = sprintf("Each line is one respondent; mean with 95%% CI in accent.\nNike: t(%d) = %.2f, %s, d_z = %.2f.  e.l.f.: t(%d) = %.2f, %s, d_z = %.2f.\nDifference between the changes (Nike minus e.l.f.): t(%d) = %.2f, %s, d_z = %.2f.",
                          as.integer(res_h3n$df), res_h3n$t, fp(res_h3n$p), res_h3n$dz, as.integer(res_h3e$df), res_h3e$t, fp(res_h3e$p), res_h3e$dz,
                          as.integer(res_h3d$df), res_h3d$t, fp(res_h3d$p), res_h3d$dz),
       x = NULL, y = "Change in mean heart rate (BPM)",
       caption = wrap_txt("SIMULATED teaching data. Heart rate is the mean of the PPG beats per minute channel over each stimulus (column name modeled; verify on the lab machine). Below the zero line = heart rate lower than in the baseline that preceded the commercial.", 125)) +
  theme_gsr() + theme(legend.position = "none")
save_fig(fig3, "SIMULATED_fig3_heart_rate_change.png", 900)

# ---- Summary tables of the tests ---------------------------------------------
row_of <- function(r, nm) tibble(id = r$id, comparison = nm, n = r$n, m_ref = r$m_1, m_cmp = r$m_2,
                                 mean_diff = r$diff, sd_diff = r$sd_diff, diff_ci_low = r$ci_lo, diff_ci_high = r$ci_hi,
                                 t = r$t, df = r$df, p = r$p, dz = r$dz, dz_ci_low = r$dz_lo, dz_ci_high = r$dz_hi,
                                 wilcoxon_V = r$V, wilcoxon_p = r$p_w, shapiro_p = r$shapiro_p)
tests <- bind_rows(
  row_of(res_h1n, "H1 Nike: Peaks Per Minute, Nike_Commercial minus Baseline_Nike"),
  row_of(res_h1e, "H1 e.l.f.: Peaks Per Minute, elf_Commercial minus Baseline_elf"),
  row_of(res_h2,  "H2 Peaks Per Minute, Nike_Commercial minus elf_Commercial"),
  row_of(res_h3n, "H3 Nike: heart rate (BPM), Nike_Commercial minus Baseline_Nike"),
  row_of(res_h3e, "H3 e.l.f.: heart rate (BPM), elf_Commercial minus Baseline_elf"),
  row_of(res_h3d, "H3 difference of heart rate changes (BPM), Nike minus e.l.f."),
  row_of(res_s1n, "Sensitivity H1 Nike, responders only"),
  row_of(res_s1e, "Sensitivity H1 e.l.f., responders only"),
  row_of(res_s2,  "Sensitivity H2, responders only"))
cat("\n---- Summary of the paired tests ----\n")
print(as.data.frame(tests %>% mutate(across(where(is.numeric), ~ round(.x, 3)))), row.names = FALSE)
write_csv(tests, "SIMULATED_test_results.csv")
cat("written: SIMULATED_test_results.csv\n")

blank <- function(analysis, term, estimate, se = NA_real_, df = NA_real_, statistic = NA_real_, p = NA_real_, lo = NA_real_, hi = NA_real_)
  tibble(analysis = analysis, term = term, estimate = estimate, se = se, df = df, statistic = statistic, p = p, ci_low = lo, ci_high = hi)
an <- "Mixed model Peaks Per Minute in the commercials"
models <- bind_rows(
  tibble(analysis = an, term = unname(term_labels[rownames(cf)]), estimate = cf$est, se = cf$se, df = cf$df,
         statistic = cf$t, p = cf$p, ci_low = cf$ci_lo, ci_high = cf$ci_hi),
  blank(an, "ICC adjusted (fitted model)", icc_adj),
  blank(an, "ICC unconditional (intercept only)", icc_null),
  blank(an, "Simple order effect estimate ((Group B - Group A) / 2)", order_simple),
  blank(an, "Simple commercial effect estimate ((Group A + Group B) / 2)", comm_simple),
  blank("Exploratory: self reported arousal with Peaks Per Minute", "r Nike", c_n$r, df = c_n$df, statistic = c_n$t, p = c_n$p, lo = c_n$lo, hi = c_n$hi),
  blank("Exploratory: self reported arousal with Peaks Per Minute", "r elf", c_e$r, df = c_e$df, statistic = c_e$t, p = c_e$p, lo = c_e$lo, hi = c_e$hi),
  blank("Exploratory: self reported arousal with Peaks Per Minute", "r respondent means", c_m$r, df = c_m$df, statistic = c_m$t, p = c_m$p, lo = c_m$lo, hi = c_m$hi),
  blank("Sensitivity: responders only", "r Nike", c_nr$r, df = c_nr$df, statistic = c_nr$t, p = c_nr$p, lo = c_nr$lo, hi = c_nr$hi),
  blank("Sensitivity: responders only", "r elf", c_er$r, df = c_er$df, statistic = c_er$t, p = c_er$p, lo = c_er$lo, hi = c_er$hi),
  blank("Sensitivity: responders only", "Simple order effect estimate ((Group B - Group A) / 2)", order_simple_r))
write_csv(models, "SIMULATED_model_results.csv")
